function res(p){ var d=p.d, T=15+p.g*d, P=26.46*d, st=p.rock, pr, out;
  if(d<0.5){ out='sed'; pr=st==='sed'?'지표에 쌓여 있음':'풍화·침식·운반'; }
  else if(T<200){ if(st==='sed'){ out='sedr'; pr='다져지고 굳어짐 (속성 작용)'; } else { out=st; pr='변화 없음 (온도가 낮아요)'; } }
  else if(T<750){ out='met'; pr=st==='met'?'열과 압력을 더 받음':'변성 작용 (열과 압력)'; }
  else { out='mag'; pr='녹아서 마그마가 됨'; }
  return {T:T,P:P,out:out,pr:pr,d1:(200-15)/p.g,d2:(750-15)/p.g}; }
