  cols:[{k:'L',l:'길이',u:'cm',d:0},{k:'Cu',l:'구리 마지막 핀',u:'s',d:1},{k:'Fe',l:'철 마지막 핀',u:'s',d:1},{k:'Gl',l:'유리 마지막 핀',u:'s',d:0}], gx:'L', gy:'Cu',
