  read:function(){ var p=this.p, tv=Math.sqrt(2*p.h/p.g), a=S.o[0], b=S.o[1]; return [['진공에서 낙하 시간',num(tv,3),'s','hl'],['땅에 닿는 속력 (진공)',num(p.g*tv,2),'m/s'],['지금 시간',num(S.t,2),'s'],['쇠공 낙하 시간',a.lt==null?'—':num(a.lt,2),'s'],['깃털 낙하 시간',b.lt==null?'—':num(b.lt,2),'s'],['깃털의 종단 속력',num(Math.sqrt(OB[1][1]*p.g/OB[1][2]),1),'m/s','th']]; },
