  cols:[{k:'mr',l:'반응한 금속',u:'g',d:3},{k:'mo',l:'결합한 산소',u:'g',d:3},{k:'tot',l:'가열 후 전체 질량',u:'g',d:3}], gx:'mr', gy:'mo', fit:true,
  fitHint:function(m,b,x,y){ if(x==='mr'&&y==='mo'&&m>1e-9) return F('기울기 {0}이므로 금속 : 산소 = 1 : {0} = {1} : 1',fmt(m,3),fmt(1/m,2)); },
  reset:function(){ H.setP('t',0); }, step:function(dt){ var t=Math.min(10,this.p.t+dt*1.2); H.setP('t',Math.round(t*100)/100); return t>=10?'done':null; },
