    var col=mix([217,130,74],[43,43,43],c.f), colM=mix([223,227,234],[244,241,232],c.f); g.fillStyle=p.mt==='cu'?col:colM; g.beginPath(); g.ellipse(cx,by-cw*0.5,cw*0.36,cw*0.1+3,0,0,TAU); g.fill();
    if(p.t>0&&p.t<9.5){ for(var i=0;i<5;i++){ var fx=cx+(i-2)*cw*0.1, fh2=18+((S.t*0+p.t*37+i*23)%18); g.fillStyle='rgba(255,'+(120+i*20)+',40,.8)'; g.beginPath(); g.moveTo(fx-7,by+8); g.quadraticCurveTo(fx,by+8-fh2*1.4,fx+7,by+8); g.fill(); } }
    tx(g,c.m[0]+' → '+c.m[1],cx,18,{al:'center',size:14,w:800,c:C.fry}); tx(g,F('가열 {0}분 · 반응한 비율 {1} %',num(p.t,1),num(c.f*100,0)),cx,Hh-14,{al:'center',size:12.5,w:700,c:TH.dim});
