    var py=sy(p.h); H.dot(g,cx,py,15,mix([79,157,255],[255,90,60],(c.Tp+10)/50),edge()); H.arrow(g,cx,py+36,cx,py+20,C.fry,2.5,8); tag(g,num(c.Tp,1)+' ℃',cx+22,py,C.fry); tx(g,'공기 덩어리',cx,py-26,{al:'center',size:11.5,w:700,c:TH.dim});
